CREATE DATABASE IF NOT EXISTS quan_ly_khach_san CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE quan_ly_khach_san;
SET NAMES utf8mb4;

-- 21 bang nghiep vu: khoa va kieu du lieu doi chieu theo CSV nguon.
CREATE TABLE CHI_NHANH (MaCN INT PRIMARY KEY, TenCN VARCHAR(180) NOT NULL, DiaChi VARCHAR(300) NOT NULL, SDT VARCHAR(20), Email VARCHAR(160) UNIQUE) ENGINE=InnoDB;
CREATE TABLE LOAI_PHONG (MaLP VARCHAR(10) PRIMARY KEY, TenLP VARCHAR(100) NOT NULL UNIQUE, MoTa TEXT, SucChua INT NOT NULL CHECK(SucChua>0)) ENGINE=InnoDB;
CREATE TABLE PHONG (MaPhong INT PRIMARY KEY, MaCN INT NOT NULL, MaLP VARCHAR(10) NOT NULL, SoPhong VARCHAR(20) NOT NULL, Tang INT NOT NULL, TrangThai ENUM('Trống','Đang sử dụng','Đã sẵn sàng','Bảo trì') NOT NULL, UNIQUE(MaCN,SoPhong), FOREIGN KEY(MaCN) REFERENCES CHI_NHANH(MaCN), FOREIGN KEY(MaLP) REFERENCES LOAI_PHONG(MaLP)) ENGINE=InnoDB;
-- NgayBD/NgayKT giu MM-DD theo du lieu nguon; MaMua/MaSuKienLe cung la ma danh muc.
CREATE TABLE BANG_GIA (MaBG VARCHAR(30) PRIMARY KEY, MaLP VARCHAR(10) NOT NULL, MaMua VARCHAR(10), TenMua VARCHAR(80), MaSuKienLe VARCHAR(30), NgayBD VARCHAR(80) NOT NULL, NgayKT VARCHAR(80) NOT NULL, GiaPhong DECIMAL(14,2) NOT NULL CHECK(GiaPhong>0), TyLeGiam DECIMAL(6,3) NOT NULL DEFAULT 0, FOREIGN KEY(MaLP) REFERENCES LOAI_PHONG(MaLP)) ENGINE=InnoDB;
CREATE TABLE KHACH_HANG (MaKH INT PRIMARY KEY, HoTen VARCHAR(160) NOT NULL, CCCD VARCHAR(25) NOT NULL UNIQUE, SDT VARCHAR(20) NOT NULL, Email VARCHAR(160), DiaChi VARCHAR(300)) ENGINE=InnoDB;
CREATE TABLE DAT_PHONG (MaDP INT PRIMARY KEY, MaKH INT NOT NULL, NgayDat DATETIME NOT NULL, TrangThai VARCHAR(40) NOT NULL, GhiChu TEXT, FOREIGN KEY(MaKH) REFERENCES KHACH_HANG(MaKH)) ENGINE=InnoDB;
CREATE TABLE CT_DAT_PHONG (MaCTDP INT PRIMARY KEY, MaDP INT NOT NULL, MaPhong INT NOT NULL, NgayCheckIn DATE NOT NULL, NgayCheckOut DATE NOT NULL, GiaThoaThuan DECIMAL(14,2) NOT NULL CHECK(GiaThoaThuan>=0), CHECK(NgayCheckOut>NgayCheckIn), UNIQUE(MaDP,MaPhong), FOREIGN KEY(MaDP) REFERENCES DAT_PHONG(MaDP), FOREIGN KEY(MaPhong) REFERENCES PHONG(MaPhong)) ENGINE=InnoDB;
CREATE TABLE DICH_VU (MaDV INT PRIMARY KEY, TenDV VARCHAR(180) NOT NULL, LoaiDV VARCHAR(50) NOT NULL, MoTa TEXT) ENGINE=InnoDB;
CREATE TABLE DV_CHI_NHANH (MaCN INT NOT NULL, MaDV INT NOT NULL, DonGia DECIMAL(14,2) NOT NULL CHECK(DonGia>=0), TrangThai VARCHAR(30) NOT NULL, PRIMARY KEY(MaCN,MaDV), FOREIGN KEY(MaCN) REFERENCES CHI_NHANH(MaCN), FOREIGN KEY(MaDV) REFERENCES DICH_VU(MaDV)) ENGINE=InnoDB;
CREATE TABLE SU_DUNG_DV (MaSD INT PRIMARY KEY, MaDP INT NOT NULL, MaCN INT NOT NULL, MaDV INT NOT NULL, ThoiGianSD DATETIME NOT NULL, SoLuong INT NOT NULL CHECK(SoLuong>0), DonGiaTaiThoiDiem DECIMAL(14,2) NOT NULL CHECK(DonGiaTaiThoiDiem>=0), FOREIGN KEY(MaDP) REFERENCES DAT_PHONG(MaDP), FOREIGN KEY(MaCN,MaDV) REFERENCES DV_CHI_NHANH(MaCN,MaDV)) ENGINE=InnoDB;
CREATE TABLE NHAN_VIEN (MaNV INT PRIMARY KEY, MaCN INT NOT NULL, HoTen VARCHAR(160) NOT NULL, SDT VARCHAR(20) NOT NULL, Email VARCHAR(160) UNIQUE, ChucVu VARCHAR(80) NOT NULL, NgayVaoLam DATE NOT NULL, FOREIGN KEY(MaCN) REFERENCES CHI_NHANH(MaCN)) ENGINE=InnoDB;
CREATE TABLE CA_LAM (MaCa INT PRIMARY KEY, TenCa VARCHAR(150) NOT NULL, GioBD TIME NOT NULL, GioKT TIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE PHAN_CA (MaPhanCa INT PRIMARY KEY, MaNV INT NOT NULL, MaCa INT NOT NULL, NgayLam DATE NOT NULL, UNIQUE(MaNV,MaCa,NgayLam), FOREIGN KEY(MaNV) REFERENCES NHAN_VIEN(MaNV), FOREIGN KEY(MaCa) REFERENCES CA_LAM(MaCa)) ENGINE=InnoDB;
CREATE TABLE HOA_DON (MaHD INT PRIMARY KEY, MaDP INT NOT NULL UNIQUE, NgayLap DATETIME NOT NULL, TongTien DECIMAL(16,2) NOT NULL DEFAULT 0 CHECK(TongTien>=0), TienCoc DECIMAL(16,2) NOT NULL DEFAULT 0 CHECK(TienCoc>=0), TrangThai VARCHAR(40) NOT NULL, FOREIGN KEY(MaDP) REFERENCES DAT_PHONG(MaDP)) ENGINE=InnoDB;
CREATE TABLE CT_HOA_DON (MaCTHD INT PRIMARY KEY, MaHD INT NOT NULL, LoaiKhoanThu VARCHAR(50) NOT NULL, MoTa VARCHAR(300) NOT NULL, SoLuong DECIMAL(12,2) NOT NULL CHECK(SoLuong>0), DonGia DECIMAL(14,2) NOT NULL CHECK(DonGia>=0), FOREIGN KEY(MaHD) REFERENCES HOA_DON(MaHD)) ENGINE=InnoDB;
CREATE TABLE GIAO_DICH_THANH_TOAN (MaGiaoDich INT PRIMARY KEY, MaHD INT NOT NULL, CongThanhToan VARCHAR(40) NOT NULL, MaGiaoDichCong VARCHAR(120), SoTien DECIMAL(16,2) NOT NULL CHECK(SoTien>0), ThoiGianGD DATETIME NOT NULL, TrangThai VARCHAR(40) NOT NULL, NoiDungChuyenKhoan VARCHAR(300), FOREIGN KEY(MaHD) REFERENCES HOA_DON(MaHD), UNIQUE(CongThanhToan,MaGiaoDichCong)) ENGINE=InnoDB;
CREATE TABLE GOI_COMBO (MaCombo INT PRIMARY KEY, MaCN INT NOT NULL, MaLP VARCHAR(10) NOT NULL, TenCombo VARCHAR(250) NOT NULL, SoNgayLuuTru INT NOT NULL, BaoGomVeVuiChoi BOOLEAN NOT NULL, BaoGomBuffet BOOLEAN NOT NULL, BaoGomDonSanBay BOOLEAN NOT NULL, GiaGoi DECIMAL(16,2) NOT NULL, MoTa TEXT, FOREIGN KEY(MaCN) REFERENCES CHI_NHANH(MaCN), FOREIGN KEY(MaLP) REFERENCES LOAI_PHONG(MaLP)) ENGINE=InnoDB;
CREATE TABLE KHU_VUI_CHOI (MaKhu INT PRIMARY KEY, MaCN INT NOT NULL, TenKhu VARCHAR(200) NOT NULL, LoaiKhu VARCHAR(100) NOT NULL, GioMoCua TIME NOT NULL, GioDongCua TIME NOT NULL, MoTa TEXT, FOREIGN KEY(MaCN) REFERENCES CHI_NHANH(MaCN)) ENGINE=InnoDB;
CREATE TABLE LOAI_VE (MaLoaiVe INT PRIMARY KEY, MaKhu INT NOT NULL, TenLoaiVe VARCHAR(200) NOT NULL, DoiTuong VARCHAR(100) NOT NULL, GiaVe DECIMAL(14,2) NOT NULL, KhungGio VARCHAR(80), MoTa TEXT, FOREIGN KEY(MaKhu) REFERENCES KHU_VUI_CHOI(MaKhu)) ENGINE=InnoDB;
CREATE TABLE VE_DIEN_TU (MaVe INT PRIMARY KEY, MaDP INT NOT NULL, MaKH INT NOT NULL, MaLoaiVe INT NOT NULL, MaQR VARCHAR(120) NOT NULL UNIQUE, NgaySuDung DATE NOT NULL, GiaTien DECIMAL(14,2) NOT NULL, TrangThai VARCHAR(40) NOT NULL, ThoiGianQuet DATETIME NULL, FOREIGN KEY(MaDP) REFERENCES DAT_PHONG(MaDP), FOREIGN KEY(MaKH) REFERENCES KHACH_HANG(MaKH), FOREIGN KEY(MaLoaiVe) REFERENCES LOAI_VE(MaLoaiVe)) ENGINE=InnoDB;
CREATE TABLE MA_GIAM_GIA (MaVoucher INT PRIMARY KEY, Code VARCHAR(60) NOT NULL UNIQUE, LoaiGiam VARCHAR(50) NOT NULL, GiaTriGiam DECIMAL(14,2) NOT NULL, DonHangToiThieu DECIMAL(14,2) NOT NULL, GiamToiDa DECIMAL(14,2), SoLuongPhatHanh INT NOT NULL, SoLuongDaDung INT NOT NULL, NgayBatDau DATE NOT NULL, NgayKetThuc DATE NOT NULL, TrangThai VARCHAR(30) NOT NULL) ENGINE=InnoDB;

-- 7 bang RBAC
CREATE TABLE TAI_KHOAN (MaTK BIGINT AUTO_INCREMENT PRIMARY KEY, TenDangNhap VARCHAR(60) NOT NULL UNIQUE, MatKhauHash VARCHAR(255) NOT NULL, Email VARCHAR(160) UNIQUE, TrangThai ENUM('Hoạt động','Bị khóa','Chờ xác minh') NOT NULL DEFAULT 'Hoạt động', MaNV INT NULL UNIQUE, MaKH INT NULL UNIQUE, NgayTao DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(NOT(MaNV IS NOT NULL AND MaKH IS NOT NULL)), FOREIGN KEY(MaNV) REFERENCES NHAN_VIEN(MaNV), FOREIGN KEY(MaKH) REFERENCES KHACH_HANG(MaKH)) ENGINE=InnoDB;
CREATE TABLE VAI_TRO (MaVaiTro INT AUTO_INCREMENT PRIMARY KEY, MaCode VARCHAR(40) NOT NULL UNIQUE, TenVaiTro VARCHAR(100) NOT NULL UNIQUE, MoTa VARCHAR(255)) ENGINE=InnoDB;
CREATE TABLE QUYEN (MaQuyen INT AUTO_INCREMENT PRIMARY KEY, MaCode VARCHAR(100) NOT NULL UNIQUE, TenQuyen VARCHAR(150) NOT NULL, NhomQuyen VARCHAR(80) NOT NULL) ENGINE=InnoDB;
CREATE TABLE VAI_TRO_QUYEN (MaVaiTro INT NOT NULL, MaQuyen INT NOT NULL, PRIMARY KEY(MaVaiTro,MaQuyen), FOREIGN KEY(MaVaiTro) REFERENCES VAI_TRO(MaVaiTro), FOREIGN KEY(MaQuyen) REFERENCES QUYEN(MaQuyen)) ENGINE=InnoDB;
CREATE TABLE TAI_KHOAN_VAI_TRO (MaTK BIGINT NOT NULL, MaVaiTro INT NOT NULL, NgayGan DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, MaNguoiGan BIGINT NULL, PRIMARY KEY(MaTK,MaVaiTro), FOREIGN KEY(MaTK) REFERENCES TAI_KHOAN(MaTK), FOREIGN KEY(MaVaiTro) REFERENCES VAI_TRO(MaVaiTro), FOREIGN KEY(MaNguoiGan) REFERENCES TAI_KHOAN(MaTK)) ENGINE=InnoDB;
CREATE TABLE PHAN_CONG_CHI_NHANH (MaTK BIGINT NOT NULL, MaCN INT NOT NULL, VaiTroTaiCN VARCHAR(40) NOT NULL, NgayBatDau DATE NOT NULL, NgayKetThuc DATE NULL, PRIMARY KEY(MaTK,MaCN,VaiTroTaiCN), CHECK(NgayKetThuc IS NULL OR NgayKetThuc>=NgayBatDau), FOREIGN KEY(MaTK) REFERENCES TAI_KHOAN(MaTK), FOREIGN KEY(MaCN) REFERENCES CHI_NHANH(MaCN)) ENGINE=InnoDB;
CREATE TABLE NHAT_KY_HOAT_DONG (MaNhatKy BIGINT AUTO_INCREMENT PRIMARY KEY, MaTK BIGINT NULL, HanhDong VARCHAR(100) NOT NULL, BangDuLieu VARCHAR(80) NOT NULL, KhoaBanGhi VARCHAR(100), GiaTriCu JSON NULL, GiaTriMoi JSON NULL, LyDo VARCHAR(500), ThoiGian DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(MaTK) REFERENCES TAI_KHOAN(MaTK)) ENGINE=InnoDB;

CREATE INDEX IDX_DATPHONG_TRANGTHAI ON DAT_PHONG(TrangThai);
CREATE INDEX IDX_CTDP_PHONG_NGAY ON CT_DAT_PHONG(MaPhong,NgayCheckIn,NgayCheckOut);
CREATE INDEX IDX_SDDV_THOIGIAN ON SU_DUNG_DV(ThoiGianSD);
CREATE INDEX IDX_HOADON_NGAY ON HOA_DON(NgayLap);
CREATE INDEX IDX_GD_HD_TT ON GIAO_DICH_THANH_TOAN(MaHD,TrangThai);
CREATE INDEX IDX_PHANCONG_CN_NGAY ON PHAN_CONG_CHI_NHANH(MaCN,NgayBatDau,NgayKetThuc);
